    /** (1 to 20) */
    count?: number;
    shape?: ("rectangle" | "roundedrectangle" | "ellipse" | "circle" | "star" | "triangle" | "pentagon" | "hexagon" | "octagon" | "trapezium" | "parallelogram" | "rarrow" | "larrow" | "diamond" | "stickynote") | {
