    /** (at most 10000 characters) */
    text?: string;
    /** (-1000000 to 1000000) */
    x?: number;
    /** (-1000000 to 1000000) */
    y?: number;
    /** (20 to 5000) */
    width?: number;
    /** (20 to 5000) */
    height?: number;
