      animation?: "mystery" | "fadeSlideUp" | "fadeSlideDown" | "bumpUpIn" | "bumpDownIn" | "impactSlide" | "powerSmash" | "torqueWarp" | "unroll" | "smoke" | "fractured" | "flux" | "springy" | "breathe" | "pulse" | "rotate" | null;
