      labelPosition?: number;
      showParentArrow?: boolean;
      showChildArrow?: boolean;
      ends?: "follow" | "pinned";
      fromEnd?: "follow" | "pinned" | "top" | "right" | "bottom" | "left";
      toEnd?: "follow" | "pinned" | "top" | "right" | "bottom" | "left";
      /** (1–200 characters) */
      toNote?: string;
      /** (1–200 characters) */
      fromNote?: string;
      toPoint?: {
        x: number;
        y: number;
      };
      fromPoint?: {
        x: number;
        y: number;
      };
      /** (1–200 characters) */
      name?: string;
      /** (at most 5000 characters) */
      description?: string;
      background?: {
        /** A CSS colour, such as #336699. (at most 64 characters) */
        color: string;
        gradient?: {
          type: "linear" | "radial";
          /** (2–8 items) */
          colors: string[];
          direction?: "horizontal" | "vertical" | "diagonal";
        };
      };
      mindMapMode?: boolean;
      autoResizeNodesBasedOnText?: boolean;
      showGrid?: boolean;
      snapToObjects?: boolean;
      /** A CSS colour, such as #336699. (at most 64 characters) */
      defaultLineColor?: string;
    };
  }>;
}

